function ct_details_read(array $s):array{$r=crm_query('SELECT * FROM nd_lc_customer_details WHERE order_id=? ORDER BY id DESC LIMIT 1',[$s['order_id']])->fetch();$data=$r?json_decode($r['data_json'],true):array_fill_keys(array_keys(ct_party_labels()),'');if(!$r){$c=crm_record('customers',(int)$s['customer_id']);$data['name']=$c['name'];$data['email']=$c['email']??'';}$out=['ok'=>true,'id'=>(int)($r['id']??0),'state'=>$r['state']??'DRAFT','reason'=>$r['review_reason']??'','data'=>$data,'labels'=>ct_party_labels(),'email_verified'=>false];return $out;}
function ct_review_details(array $d):array{$id=cc_id($d['id']??null);$r=crm_query('SELECT * FROM nd_lc_customer_details WHERE id=? FOR UPDATE',[$id])->fetch();if(!$r)crm_fail(404,'Данные не найдены.');$latest=crm_query('SELECT id FROM nd_lc_customer_details WHERE order_id=? ORDER BY id DESC LIMIT 1',[$r['order_id']])->fetchColumn();if((int)$latest!==$id)crm_fail(409,'Есть новая версия данных.');crm_version($d,$r);if($r['state']!=='SUBMITTED')crm_fail(409,'Нет новой отправленной версии.');$reason=cc_text($d,'reason',3000);$state=($d['approve']??false)===true?'APPROVED':'CORRECTION';$authority=cc_text($d,'authority_review',3000,$state==='APPROVED');$data=json_decode($r['data_json'],true);if($state==='APPROVED')ct_validate_party($data);crm_query('UPDATE nd_lc_customer_details SET state=?,review_reason=?,authority_review=?,version=version+1 WHERE id=?',[$state,$reason,$authority,$id]);lc_audit(['type'=>'owner','id'=>1],'customer_details',$id,$state,(int)$r['version'],['hash'=>$r['checksum'],'email_verified'=>false]);return ['ok'=>true,'id'=>$id];}
