/** Only the new catalog revision opts in. Historical customer snapshots never re-render. */
function ct_json_rows(string $text,string $label,bool $empty=false):array{
 $rows=json_decode($text,true);if(!is_array($rows)||!array_is_list($rows)||(!$empty&&!$rows))crm_fail(422,$label.': нужен список JSON.');foreach($rows as $row)if(!is_array($row)||array_is_list($row))crm_fail(422,$label.': проверьте строку.');return $rows;
}
function ct_row_text(array $r,array $keys):void{foreach($keys as $key)if(!isset($r[$key])||!is_string($r[$key])||trim($r[$key])==='')crm_fail(422,'Обязательное поле строки: '.$key);}
function ct_terms_v2(array $v,int $minor,array $schedule,string $kind):array{
 ct_required($v,['price.rights_fee','support.start_event','support.duration']);if(bill_minor($v['price.rights_fee'])>$minor)crm_fail(422,'Вознаграждение за права входит в цену и не превышает её.');
 $sum=0;$lines=[];$gates=['production'=>'начало производства','milestone'=>'этап','acceptance'=>'приёмка','handover'=>'передача','closure'=>'завершение','none'=>'без дополнительного условия'];
 foreach($schedule as $i=>$row){$sum+=(int)$row['amount_minor'];$position=count($schedule)===1?'первоначальный и окончательный':($i===0?'первоначальный':($i===count($schedule)-1?'окончательный':'промежуточный'));$lines[]=($i+1).'. '.$row['label'].' ('.$position.'): '.bill_decimal((int)$row['amount_minor']).' руб.; срок '.$row['due_on'].'; условие: '.($gates[$row['gate']]??$row['gate']).($row['stage_id']?'; этап №'.$row['stage_id']:'').'.';}
 if($sum!==$minor)crm_fail(422,'Сумма единого графика не совпадает с ценой.');$v['payment.schedule']=implode("\n",$lines);
 if($kind!=='specification')return $v;
 ct_required($v,['project.name','project.purpose','project.type','project.audience','spec.completion_deadline','support.end_calculation','support.end_date','support.response_time','support.defect_procedure']);
 $rows=ct_json_rows($v['spec.milestones']??'','Этапы');$sum=0;$lines=[];$previousEnd=null;
 foreach($rows as $i=>$row){ct_row_text($row,['result','criteria','dependencies','amount']);$amount=bill_minor($row['amount']);$sum+=$amount;$fixed=isset($row['start_on'])&&trim((string)$row['start_on'])!=='';$relative=isset($row['start_condition'])&&trim((string)$row['start_condition'])!=='';
 if($fixed===$relative)crm_fail(422,'Этап: выберите дату начала либо объективное условие.');
 if($fixed){if(!ct_iso_date($row['start_on'])||!is_string($row['due_on']??null)||!ct_iso_date($row['due_on'])||$row['due_on']<$row['start_on']||!empty($row['duration_days'])||!empty($row['day_type']))crm_fail(422,'Фиксированный этап: даты начала и окончания без второго относительного срока.');$days=(new DateTimeImmutable($row['start_on']))->diff(new DateTimeImmutable($row['due_on']))->days+1;$timing='с '.$row['start_on'].' по '.$row['due_on'].' включительно; '.$days.' календарных дней';$previousEnd=$row['due_on'];
 }else{ct_row_text($row,['start_condition','day_type']);if(!is_int($row['duration_days']??null)||$row['duration_days']<1||$row['duration_days']>3650||!in_array($row['day_type'],['calendar','business'],true)||!empty($row['due_on']))crm_fail(422,'Относительный этап: положительная длительность и calendar/business, без конфликтующей даты.');$timing='начало после: '.$row['start_condition'].'; '.$row['duration_days'].($row['day_type']==='business'?' рабочих':' календарных').' дней со следующего дня после подтверждённого события';}
 $lines[]=($i+1).'. '.$row['result']."\nСрок: ".$timing."\nЗависимости и материалы: ".$row['dependencies']."\nКритерии: ".$row['criteria']."\nСтоимость результата (не дополнительный платёж): ".bill_decimal($amount).' руб.';
 }
 if($sum!==$minor)crm_fail(422,'Стоимость результатов этапов не равна цене.');if(ct_iso_date($v['spec.completion_deadline']))foreach($rows as $row)if(!empty($row['due_on'])&&$row['due_on']>$v['spec.completion_deadline'])crm_fail(422,'Конечный срок раньше срока этапа.');$v['spec.milestones']=implode("\n\n",$lines);
 $lines=[];foreach(ct_json_rows($v['spec.acceptance_criteria']??'','Проверяемые сценарии') as $i=>$row){ct_row_text($row,['role','scenario','result','environment','conditions','version']);$lines[]=($i+1).'. Роль: '.$row['role'].'; сценарий: '.$row['scenario']."\nОжидается: ".$row['result']."\nСреда: ".$row['environment'].'; условия: '.$row['conditions'].'; версия: '.$row['version'];}$v['spec.acceptance_criteria']=implode("\n\n",$lines);
 $lines=[];foreach(ct_json_rows($v['spec.recurring_costs']??'','Регулярные расходы',true) as $row){ct_row_text($row,['name','amount','period','payer']);bill_minor($row['amount']);if(!is_bool($row['included']??null))crm_fail(422,'Укажите включение расхода в цену: true/false.');$lines[]=$row['name'].': '.$row['amount'].' руб. / '.$row['period'].'; плательщик '.$row['payer'].'; '.($row['included']?'включено в общую цену':'отдельно, не включено в цену');}$v['spec.recurring_costs']=$lines?implode("\n",$lines):'Регулярные внешние расходы не предусмотрены.';
