/** Prepare both separate PDFs from one explicitly confirmed set of terms. */
function ct_generate_pair(array $a,array $d):array{
 $ids=$d['template_ids']??null;if(!is_array($ids)||!array_is_list($ids)||count($ids)!==2)crm_fail(422,'Нужны два отдельных шаблона: договор и ТЗ.');
 $kinds=[];$requests=[];foreach($ids as $id){$t=lc_template(cc_id($id));$kinds[]=$t['kind'];$requests[]=['template_id'=>$id,'terms_id'=>cc_id($d['terms_id']??null)];}sort($kinds);if($kinds!==['agreement','specification'])crm_fail(422,'Выберите договор и ТЗ одного комплекта.');
 // Validate both documents before creating either binding or private asset.
 foreach($requests as $request)ct_generate($a,$request,true);
 $out=[];try{foreach($requests as $request){$result=ct_generate($a,$request);$out[]=['id'=>$result['id'],'kind'=>$result['record']['kind']];}}catch(Throwable $e){foreach($out as $created){try{$asset=ct_asset(lc_binding($a,$created['id']));$path=cc_file_path($asset);if(is_file($path))unlink($path);}catch(Throwable $cleanup){error_log('contract_pair_asset_cleanup_failed');}}throw $e;}
 return ['ok'=>true,'documents'=>$out];
}
